1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
26	import {log} from '../shared/logger.js';
27	
28	const DEFAULT_MAX_TOOL_ROUNDS = 5;
29	
30	export interface OrchestratorHooks {
31	  beforeSession?: (session: ChatSession) => Promise<void>;
32	  afterSession?: (session: ChatSession) => Promise<void>;
33	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
34	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
35	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
36	  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: UsageMetadata) => Promise<void>;
37	  onError?: (session: ChatSession, error: Error) => Promise<void>;
38	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
39	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
40	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
41	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
42	}
43	
44	export interface ToolBudgetInfo {
45	  maxToolRounds: number;
46	  requestedTools: string[];
47	}
48	
49	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
50	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
51	
52	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
53	
54	export interface ChatOrchestrator {
55	  processMessage(session: ChatSession): Promise<string>;
56	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
57	}
58	
59	export interface ChatOrchestratorOptions {
60	  maxToolRounds?: number;
61	  contextConfig?: Partial<ContextConfig>;
62	  promptBuilderOptions?: PromptBuilderOptions;
63	  hooks?: OrchestratorHooks;
64	  sessionStore?: SessionStore;
65	}
66	
67	interface ToolExecutionResult {
68	  clientMessages: OutgoingMessage[];
69	  suppressOutput: boolean;
70	}
71	export function createChatOrchestrator(
72	  provider: AIProvider,
73	  promptBuilder: PromptBuilder,
74	  toolRegistry?: ToolRegistry,
75	  options?: ChatOrchestratorOptions
76	): ChatOrchestrator {
77	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
78	  const contextConfig = createContextConfig(options?.contextConfig);
79	  const toolInstructions = toolRegistry?.getPromptInstructions();
80	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
81	  const tools = toolRegistry?.getDefinitions();
82	  const hooks = options?.hooks;
83	  const sessionStore = options?.sessionStore;
84	
85	  return {
86	    async processMessage(session: ChatSession): Promise<string> {
87	      return collectText(this.processMessageStream(session));
88	    },
89	
90	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
91	      try {
92	        if (hooks?.beforeSession) await hooks.beforeSession(session);
93	
94	        let userMessage = lastUserContent(session);
95	
96	        if (hooks?.beforeUserInput) {
97	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
98	        }
99	
100	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
101	
102	        const systemPrompt = hooks?.beforeModelResponse
103	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
104	          : baseSystemPrompt;
105	
106	        const messages: Message[] = toMessages(session.entries, contextConfig);
107	        let totalUsage: UsageMetadata | undefined;
108	        let responseText = '';
109	
110	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
111	        for (let round = 0; ; round++) {
112	          log.info('orchestrator', 'starting round', {round});
113	          const pendingToolCalls: ToolCall[] = [];
114	
115	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
116	          responseText += outcome.text;
117	          totalUsage = accumulateUsage(totalUsage, outcome.usage);
118	
119	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
120	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
121	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
122	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
123	            break;
124	          }
125	
126	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
127	          const {clientMessages, suppressOutput} = await executeToolCalls(
128	            pendingToolCalls,
129	            messages,
130	            session,
131	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
132	          );
133	          log.info('orchestrator', 'tool execution complete', {
134	            clientMessageCount: clientMessages.length,
135	            clientMessageTypes: clientMessages.map(m => m.type),
136	            suppressOutput,
137	          });
138	
139	          if (clientMessages.length > 0) {
140	            yield {type: 'tool_result' as const, clientMessages};
141	          }
142	
143	          if (suppressOutput) {
144	            yield {type: 'suppress_output' as const};
145	          }
146	        }
147	
148	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
149	      } catch (error) {
150	        // The hook is typed against Error, so a rejection that is not one is wrapped for it; the caller keeps the original.
151	        if (hooks?.onError) await hooks.onError(session, asError(error));
152	        throw error;
153	      } finally {
154	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
155	        commitStreamingEntries(session);
156	        try {
157	          if (hooks?.afterSession) await hooks.afterSession(session);
158	        } finally {
159	          await saveSession(sessionStore, session);
160	        }
161	      }
162	    },
163	  };
164	}
165	
166	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
167	function normalizeToolRounds(value: number | undefined): number {
168	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
169	  return Math.max(0, Math.floor(value));
170	}
171	
172	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
173	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
174	  if (round < maxToolRounds) return false;
175	  log.warn('orchestrator', 'tool budget exhausted', {
176	    maxToolRounds,
177	    requestedTools: pendingToolCalls.map(tc => tc.name),
178	  });
179	  return true;
180	}
181	
182	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
183	async function* closeExhaustedTurn(
184	  session: ChatSession,
185	  budget: ToolBudgetInfo,
186	  hook?: OnToolBudgetExhausted
187	): AsyncGenerator<MessageChunk, string> {
188	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
189	  if (sentence !== '') yield {type: 'text', text: sentence};
190	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
191	  return sentence;
192	}
193	
194	interface RoundOutcome {
195	  stopReason: string;
196	  text: string;
197	  usage?: UsageMetadata;
198	}
199	
200	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
201	async function* streamRound(
202	  provider: AIProvider,
203	  request: SendMessageParams,
204	  pendingToolCalls: ToolCall[]
205	): AsyncGenerator<MessageChunk, RoundOutcome> {
206	  let stopReason = '';
207	  let text = '';
208	  let usage: UsageMetadata | undefined;
209	
210	  for await (const chunk of provider.sendMessage(request)) {
211	    yield chunk;
212	    collectToolCalls(chunk, pendingToolCalls);
213	    stopReason = extractStopReason(chunk) ?? stopReason;
214	    usage = extractUsage(chunk) ?? usage;
215	    if (chunk.type === 'text') text += chunk.text;
216	  }
217	
218	  return {stopReason, text, usage};
219	}
220	
221	// A changed message is also written back to the session's last user entry.
222	async function rewriteUserMessage(
223	  session: ChatSession,
224	  userMessage: string,
225	  hook: (session: ChatSession, userMessage: string) => Promise<string>
226	): Promise<string> {
227	  const modified = await hook(session, userMessage);
228	  if (modified === userMessage) return userMessage;
229	
230	  updateLastUserContent(session, modified);
231	  return modified;
232	}
233	
234	function lastUserContent(session: ChatSession): string {
235	  for (let i = session.entries.length - 1; i >= 0; i--) {
236	    const entry = session.entries[i];
237	    if (entry.role === 'user') return entry.content;
238	  }
239	  return '';
240	}
241	
242	function updateLastUserContent(session: ChatSession, content: string): void {
243	  for (let i = session.entries.length - 1; i >= 0; i--) {
244	    const entry = session.entries[i];
245	    if (entry.role === 'user') {
246	      entry.content = content;
247	      return;
248	    }
249	  }
250	}
251	
252	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
253	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
254	  const context: ToolContext = {
255	    userId: session.userId,
256	    sessionId: session.sessionId,
257	    workspaceId: session.workspaceId,
258	    authHeaders: session.authHeaders,
259	  };
260	
261	  return async (tc: ToolCall): Promise<ToolResponse> => {
262	    const declined =
263	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
264	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
265	  };
266	}
267	
268	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
269	async function consultPolicy(
270	  policy: BeforeToolCall,
271	  session: ChatSession,
272	  tc: ToolCall
273	): Promise<ToolResponse | undefined> {
274	  try {
275	    return await policy(session, tc);
276	  } catch (error) {
277	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
278	      tool: tc.name,
279	      errorType: error instanceof Error ? error.name : typeof error,
280	    });
281	    return {result: `The ${tc.name} call was declined and not performed.`};
282	  }
283	}
284	
285	async function executeToolCalls(
286	  pendingToolCalls: ToolCall[],
287	  messages: Message[],
288	  session: ChatSession,
289	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
290	): Promise<ToolExecutionResult> {
291	  messages.push(buildToolCallMessages(pendingToolCalls));
292	
293	  const responses = await Promise.all(
294	    pendingToolCalls.map(async tc => {
295	      const response = await runToolCall(tc);
296	      return {tc, response};
297	    })
298	  );
299	
300	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
301	    type: 'tool_result' as const,
302	    toolUseId: tc.id,
303	    content: response.result,
304	  }));
305	  messages.push({role: 'user', content: toolResults});
306	
307	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
308	
309	  return {
310	    clientMessages: assignEntryIndices(rawClientMessages, session),
311	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
312	  };
313	}
314	
315	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
316	  return clientMessages.map(msg => {
317	    if (msg.type !== 'entry_upsert') return msg;
318	    const index = appendEntry(session, msg.entry);
319	    return {...msg, index};
320	  });
321	}
322	
323	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
324	function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
325	  if (!acc) return next;
326	  if (!next) return acc;
327	  return {
328	    inputTokens: acc.inputTokens + next.inputTokens,
329	    outputTokens: acc.outputTokens + next.outputTokens,
330	    totalTokens: acc.totalTokens + next.totalTokens,
331	  };
332	}
333	
334	// onError is typed against Error, so a rejection that is not one is wrapped for the hook; the caller still receives the original.
335	function asError(rejection: unknown): Error {
336	  if (rejection instanceof Error) return rejection;
337	  const message = typeof rejection === 'string' ? rejection : describeRejection(rejection);
338	  return new Error(message, {cause: rejection});
339	}
340	
341	// JSON.stringify refuses circular structures and returns undefined for values it cannot render; String() then names what was thrown.
342	function describeRejection(rejection: unknown): string {
343	  try {
344	    return JSON.stringify(rejection) ?? String(rejection);
345	  } catch {
346	    return String(rejection);
347	  }
348	}
349	
350	// A store outage is not a reason to fail the turn the customer already received.
351	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
352	  if (!store?.save) return;
353	
354	  try {
355	    await store.save(session);
356	  } catch (error) {
357	    const message = error instanceof Error ? error.message : String(error);
358	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
359	  }
360	}
