1	/**
2	 * no-catch-as-control-flow — flag a catch clause that swallows the error AND
3	 * fabricates a return value (returns a call/constructor result). That shape is
4	 * try/catch used as an if: the error is not handled, it is silently traded for
5	 * an alternate code path. Wrap only the throwing call in a status-returning
6	 * probe (`catch { return null; }` — a sentinel fallback is fine), or observe
7	 * the error (log/rethrow/map it) before returning a response.
8	 *
9	 * Detect-only: the fix (a probe function, an error log) needs human judgment.
10	 *
11	 * A catch *swallows* when it has no parameter or never references it. A catch
12	 * *fabricates* when a return statement in its own scope (not a nested
13	 * function) returns a call, constructor, or awaited-call result — literals,
14	 * identifiers and object literals are sentinel fallbacks and stay legal.
15	 */
16	const FUNCTION_TYPES = new Set([
17	    "FunctionDeclaration",
18	    "FunctionExpression",
19	    "ArrowFunctionExpression",
20	]);
21	const FABRICATING_TYPES = new Set(["CallExpression", "NewExpression"]);
22	function isAstNode(value) {
23	    return Boolean(value) && typeof value.type === "string";
24	}
25	function childNodes(node) {
26	    return Object.keys(node)
27	        .filter((key) => key !== "parent")
28	        .flatMap((key) => {
29	        const value = node[key];
30	        return Array.isArray(value) ? value : [value];
31	    })
32	        .filter(isAstNode);
33	}
34	function referencesName(node, name) {
35	    if (!isAstNode(node))
36	        return false;
37	    if (node.type === "Identifier")
38	        return node.name === name;
39	    return childNodes(node).some((child) => referencesName(child, name));
40	}
41	/** Return statements in the catch's own scope — nested functions excluded. */
42	function ownReturns(node, acc = []) {
43	    if (!isAstNode(node))
44	        return acc;
45	    if (FUNCTION_TYPES.has(node.type))
46	        return acc;
47	    if (node.type === "ReturnStatement") {
48	        acc.push(node);
49	        return acc;
50	    }
51	    childNodes(node).forEach((child) => ownReturns(child, acc));
52	    return acc;
53	}
54	function fabricatesValue(returnStatement) {
55	    let argument = returnStatement.argument;
56	    if (!argument)
57	        return false;
58	    if (argument.type === "AwaitExpression")
59	        argument = argument.argument;
60	    return FABRICATING_TYPES.has(argument.type);
61	}
62	function swallowsError(catchClause) {
63	    if (!catchClause.param)
64	        return true;
65	    if (catchClause.param.type !== "Identifier")
66	        return false;
67	    return !referencesName(catchClause.body, catchClause.param.name);
68	}
69	export default {
70	    meta: {
71	        type: "problem",
72	        docs: {
73	            description: "disallow catch clauses that swallow the error and fabricate a return value (try/catch as control flow)",
74	        },
75	        schema: [],
76	        messages: {
77	            catchAsControlFlow: "This catch swallows the error and fabricates a return value — try/catch as control flow. Wrap only the throwing call in a status-returning probe, or observe the error before mapping it.",
78	        },
79	    },
80	    create(context) {
81	        return {
82	            CatchClause(node) {
83	                if (!swallowsError(node))
84	                    return;
85	                if (!ownReturns(node.body).some(fabricatesValue))
