    found.offenders
        .filter(({ category }) => !found.tamed.has(category))
        .forEach(({ node, call }) => context.report({ node, messageId: "nondeterministic", data: { call } }));
}
export default {
    meta: {
        type: "problem",
        docs: {
            description: "Disallow Math.random, Date.now, new Date(), performance.now and crypto.randomUUID in test files unless faked (useFakeTimers / setSystemTime / spyOn Math.random / mock crypto)",
        },
        schema: [
            {
                type: "object",
                properties: {},
                additionalProperties: false,
            },
        ],
        messages: {
            nondeterministic: "{{call}} makes this test non-repeatable; inject the value or use fake timers",
        },
    },
    create(context) {
        if (!TEST_FILE.test(context.filename)) {
            return {};
        }
        const found = { offenders: [], tamed: new Set() };
        return {
            CallExpression: (node) => collectCall(node, found),
            NewExpression: (node) => collectBareDate(node, found),
